var FORBIDDEN_EXPLANATION = /formula|let x|substitut|apply the formula|notice that|therefore, the answer is obtained|shortcut|\bAI\b/i;
function validatePct002Parameters(parameters) {
  const registryEntry = getTaskRegistryEntry2(parameters.canonicalProblemId, parameters.questionLanguageId);
  const isSharedQuestionLanguage = getCommonQuestionLanguageIds2(parameters.canonicalProblemId).includes(parameters.questionLanguageId);
  const enPlaceholders = placeholderSet2(parameters, "en");
  const hiPlaceholders = isSharedQuestionLanguage ? placeholderSet2(parameters, "hi") : null;
  const paPlaceholders = isSharedQuestionLanguage ? placeholderSet2(parameters, "pa") : null;
  const checks = [
    check2("archetype", parameters.archetypeId === PCT_002_ARCHETYPE_ID, "Archetype ID must match."),
    check2("cp", PCT_002_CP_IDS.includes(parameters.canonicalProblemId), "CP must be active."),
    check2("questionLanguage", parameters.questionLanguageId.length > 0, "Question language ID must be present."),
    check2("taskKindRegistry", parameters.taskKind === registryEntry.taskKind, "Task kind must come from task registry."),
    check2("answerTypeRegistry", parameters.answerType === registryEntry.answerType, "Answer type must come from task registry."),
    check2(
      "requiredVariablesRegistry",
      parameters.requiredVariables.join("|") === registryEntry.requiredVariables.join("|"),
      "Required variables must come from task registry."
    ),
    check2(
      "placeholderCrossLanguage",
      !isSharedQuestionLanguage || sameSet2(enPlaceholders, hiPlaceholders) && sameSet2(enPlaceholders, paPlaceholders),
      "EN/HI/PA placeholders must match for shared question-language IDs."
    ),
    check2(
      "questionLanguageRegistered",
      getQuestionLanguageIds2(parameters.canonicalProblemId, parameters.language).includes(parameters.questionLanguageId),
      "Question language must be available for the package language."
    )
  ];
  for (const variable of registryEntry.requiredVariables) {
    checks.push(check2(`requiredVariable:${variable}`, Object.hasOwn(parameters.variables, variable), `${variable} must be generated.`));
  }
  return { valid: checks.every((item) => item.passed), checks };
}
function validatePct002QuestionPackage(pkg) {
  const parameterValidation = validatePct002Parameters(pkg.parameters);
  const checks = [
    ...parameterValidation.checks,
    check2("libraryValidation", validatePct002Libraries().valid, "Libraries must be internally consistent."),
    check2("stem", pkg.stem.length > 0 && !pkg.stem.includes("undefined"), "Stem must render."),
    check2("answer", pkg.answer.length > 0 && !pkg.answer.includes("undefined") && !pkg.answer.includes("NaN"), "Answer must render."),
    check2("graphAnswer", pkg.reasoningGraph.nodes.some((node2) => node2.id === "answer"), "Graph must contain answer node."),
    check2("graphAnswerType", pkg.reasoningGraph.nodes.some((node2) => node2.id === "answerType"), "Graph must contain answer type node."),
    check2("explanation", pkg.explanation.lines.length > 0, "Explanation must render."),
    check2("explanationV21", isAlternatingV21(pkg.explanation.lines), "Explanation must alternate statement and Rightarrow consequence lines."),
    check2("noForbiddenExplanation", !FORBIDDEN_EXPLANATION.test(pkg.explanation.lines.join("\n")), "Explanation must avoid forbidden filler."),
    check2("traceability", pkg.traceability.answer === pkg.answer, "Traceability answer must match.")
  ];
  return { valid: checks.every((item) => item.passed), checks };
}

