  const targetValue = value3(parameters, "targetValue");
  const partRate = value3(parameters, "partRate");
  const totalValue = value3(parameters, "totalValue");
  const initialPartValue = totalValue * partRate / 100;
  const initialOtherValue = totalValue - initialPartValue;
  const partIncreaseRate = value3(parameters, "partIncreaseRate");
