      multiplier: growthFactor(increaseRate),
      increaseAmount: originalValue * increaseRate / 100,
      onePercentValue: taskKind === "originalValueFromIncreasedValue" ? value3(parameters, "increasedValue") / (100 + increaseRate) : "",
      afterFirstValue: taskKind === "repeatedPercentageIncrease" ? value3(parameters, "originalValue") * growthFactor(rate1) : "",
