// src/quant-v4/topics/Arithmetic/subtopics/Percentage/PCT-004/foundation/math.ts
function roundTo4(value7, places = 4) {
  const factor = 10 ** places;
  return Math.round((value7 + Number.EPSILON) * factor) / factor;
}
function formatNumber6(value7) {
  const rounded = roundTo4(value7, 4);
  if (Number.isInteger(rounded)) return String(rounded);
  return String(rounded).replace(/\.?0+$/, "");
}
function formatPercent4(value7) {
  return `${formatNumber6(value7)}%`;
}
function wrapAnswer3(answerType, raw) {
  if (answerType === "PERCENT") return `$$${raw.replace("%", "\\%")}$$`;
  if (answerType === "RATIO") return `$$${raw.replace(":", " : ")}$$`;
  return `$$${raw}$$`;
}
function stableHash4(input) {
  let hash2 = 0;
  for (let index = 0; index < input.length; index += 1) {
    hash2 = hash2 * 31 + input.charCodeAt(index) >>> 0;
  }
  return hash2;
}
function stableBucket4(seed, size) {
  if (size <= 0) return 0;
  return stableHash4(seed) % size;
}
function mathJaxBlock3(expression) {
  return `\\[\\Rightarrow ${expression}\\]`;
}
function retainedFactor(rate3) {
  return (100 - rate3) / 100;
}

