      const selectedBase = parameters.solveMode === "differenceAsPercentOfFirst" ? value1 : parameters.solveMode === "differenceAsPercentOfSecond" ? value22 : parameters.solveMode === "largerMoreThanSmaller" ? smaller : larger;
      evidence.value1 = value1;
