function buildSubstitutionLatex(taskKind, parameters, solver) {
  const n17 = (name) => numberValue(parameters, name);
  switch (taskKind) {
    case "simpleLinkage":
      return `${n17("ratioA1")}\\times${n17("ratioB2")}:${n17("ratioB1")}\\times${n17("ratioB2")}:${n17("ratioB1")}\\times${n17("ratioC2")}`;
    case "ratioNormalization":
      return `${n17("numerator1")}\\times${n17("denominator2")}:${n17("denominator1")}\\times${n17("numerator2")}`;
    case "ratioTreeLinkage":
      return `${n17("ratioA")}\\times${n17("ratioB_prime")}\\times${n17("ratioC_prime")}:${n17("ratioB")}\\times${n17("ratioC")}\\times${n17("ratioD")}`;
    case "scalingByComponent":
      return `\\frac{${n17("valueA")}}{${n17("ratioA")}}\\times${n17("ratioB")}`;
    case "decimalNormalization":
      return `${n17("decimalA")}\\times10:${n17("decimalB")}\\times10`;
    case "basicPartition": {
      const sum = n17("ratioA") + n17("ratioB") + n17("ratioC");
      const targetPerson = String(parameters.variables.targetPerson);
      const targetRatio = targetPerson === String(parameters.variables.personC) ? n17("ratioC") : targetPerson === String(parameters.variables.personB) ? n17("ratioB") : n17("ratioA");
      return `\\frac{${n17("totalAmount")}}{${sum}}\\times${targetRatio}`;
    }
    case "shareDifference": {
      const sum = n17("ratioA") + n17("ratioB") + n17("ratioC");
      return `\\frac{${n17("totalAmount")}}{${sum}}\\times(${n17("ratioA")}-${n17("ratioC")})`;
    }
    case "reversePartition": {
      const diff = n17("ratioA") - n17("ratioC");
      const sum = n17("ratioA") + n17("ratioB") + n17("ratioC");
      return `\\frac{${n17("shareDifference")}}{${diff}}\\times${sum}`;
    }
    case "salaryDistribution":
      return `\\frac{${n17("totalSalary")}}{${n17("ratioExp") + n17("ratioSav")}}\\times${n17("ratioSav")}`;
    case "twoStateAddition":
      return `${n17("finalRatioB")}(${n17("ratioA")}x+${n17("addedCount")})=${n17("finalRatioA") * n17("ratioB")}x`;
    case "twoStateSubtraction":
      return `${n17("finalRatioB")}(${n17("ratioA")}x-${n17("removedCount")})=${n17("finalRatioA") * n17("ratioB")}x`;
    case "twoStateTransfer":
      return `${n17("finalRatioB")}(${n17("ratioA")}x+${n17("transferredCount")})=${n17("finalRatioA")}(${n17("ratioB")}x-${n17("transferredCount")})`;
    case "incomeExpenditureSystem":
      return `${n17("incomeRatioA")}x-${n17("expRatioA")}y=${n17("savingsAmount")},\\ ${n17("incomeRatioB")}x-${n17("expRatioB")}y=${n17("savingsAmount")}`;
    case "multiStageTransformation":
      return `${n17("finalRatioB")}(${n17("ratioA")}x+${n17("addedCount")})=${n17("finalRatioA")}(${n17("ratioB")}x-${n17("removedCount")})`;
    case "meanProportional":
      return `x=\\sqrt{${n17("numA")}\\times${n17("numB")}}`;
    case "thirdProportional":
      return `x=\\frac{${n17("numB")}^2}{${n17("numA")}}`;
    case "fourthProportional":
      return `x=\\frac{${n17("numB")}\\times${n17("numC")}}{${n17("numA")}}`;
    case "directVariation":
      return `\\frac{${n17("varY1")}}{${n17("varX1")}}=\\frac{y}{${n17("varX2")}}`;
    case "inverseVariation":
      return `${n17("varX1")}\\times${n17("varY1")}=${n17("varX2")}\\times y`;
    case "coinCounting":
      return `x=\\frac{${n17("totalValue")}}{${n17("ratio1")}\\times${n17("denom1")}+${n17("ratio2")}\\times${n17("denom2")}+${n17("ratio3")}\\times${n17("denom3")}}`;
    case "multiDenominationMapping":
      return `\\frac{${solver.evidence.countWeight1}}{1}:\\frac{${solver.evidence.countWeight2}}{1}:\\frac{${solver.evidence.countWeight3}}{1}:\\frac{${solver.evidence.countWeight4}}{1}`;
    case "weightedMapping":
      return `\\frac{${n17("totalWeight")}}{${n17("countA")}\\times${n17("ratioA")}+${n17("countB")}\\times${n17("ratioB")}+${n17("countC")}\\times${n17("ratioC")}}`;
    case "weightedMarks":
      return `\\frac{${n17("totalScore")}}{${n17("ratio1")}\\times${n17("w1")}+${n17("ratio2")}\\times${n17("w2")}+${n17("ratio3")}\\times${n17("w3")}}`;
    case "binaryMixture":
      return `${n17("finalRatio2")}\\times${n17("addedAmount")}\\div(${n17("ratio2")}\\times${n17("finalRatio1")}-${n17("ratio1")}\\times${n17("finalRatio2")})`;
    case "mixtureComponentFinding": {
      const initial1 = Number(solver.workingValues.initial1);
      const initial2 = Number(solver.workingValues.initial2);
      return `\\frac{${initial1}\\times${n17("finalRatio2")}}{${n17("finalRatio1")}}-${initial2}`;
    }
    case "threeComponentMixture": {
      const unit = Number(solver.workingValues.unit);
      return `${unit}\\times(${n17("ratio1")}+${n17("ratio2")}+${n17("ratio3")})`;
    }
    case "variableReplacementRatio":
      return `\\left(1-\\frac{${n17("removedVolume1")}}{${n17("initialVolume")}}\\right)\\left(1-\\frac{${n17("removedVolume2")}}{${n17("initialVolume")}}\\right)`;
    case "acidConcentration":
      return `\\frac{${n17("acidVolume")}}{${n17("acidVolume") + n17("waterVolume")}}\\times100`;
    default:
      throw new Error(`Unsupported localized RAP-001 taskKind: ${taskKind}`);
  }
}
