// src/quant-v4/topics/Arithmetic/subtopics/RatioAndProportion/RAP-003/math.ts
function gcd11(a, b) {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    const next = x % y;
    x = y;
    y = next;
  }
  return x || 1;
}
function simplifyRatio3(values) {
  const divisor = values.reduce((acc, value7) => gcd11(acc, value7), 0) || 1;
  return values.map((value7) => Math.round(value7 / divisor));
}
function formatNumber12(value7) {
  if (!Number.isFinite(value7)) return String(value7);
  const rounded = Math.round(value7 * 100) / 100;
  if (Number.isInteger(rounded)) return String(rounded);
  return String(rounded).replace(/(\.\d*?)0+$/, "$1").replace(/\.$/, "");
}
function ratioLatex2(values) {
  return values.join(" : ");
}
function stableHash10(input) {
  let hash2 = 2166136261;
  for (let index = 0; index < input.length; index++) {
    hash2 ^= input.charCodeAt(index);
    hash2 = Math.imul(hash2, 16777619);
  }
  return hash2 >>> 0;
}
function stableBucket10(seed, size) {
  if (size <= 0) return 0;
  return stableHash10(seed) % size;
}
function pick10(values, seed) {
  return values[stableBucket10(seed, values.length)];
}

