function renderRap003Template(template, variables) {
  const rendered = template.replace(/\{([^}]+)\}/g, (_, key) => {
    if (variables[key] === void 0) throw new Error(`Missing template variable: ${key}`);
    return String(variables[key]);
  });
  return rendered.charAt(0).toUpperCase() + rendered.slice(1);
}

